
%% MATH 155 - Homework 1, Problem 4
% Histogram Equalization
% Norah Lynch

clear; clc; close all;

%% Read image
I = imread('HW1Q4_original_image.jpg');

if size(I, 3) == 3
    I = rgb2gray(I);
end

I = uint8(I);

%% Compute histogram of original image
L = 256;
[M, N] = size(I);
numPixels = M * N;

histOriginal = zeros(1, L);

for i = 1:M
    for j = 1:N
        grayLevel = double(I(i,j)) + 1;
        histOriginal(grayLevel) = ...
            histOriginal(grayLevel) + 1;
    end
end

%% Compute histogram equalization transformation
pdf = histOriginal / numPixels;
cdf = cumsum(pdf);
T = round((L-1) * cdf);

%% Apply T(r) to original image
Ieq = zeros(M, N, 'uint8');

for i = 1:M
    for j = 1:N
        Ieq(i,j) = uint8(T(double(I(i,j)) + 1));
    end
end

%% Histogram for enhanced image
histEnhanced = zeros(1, L);

for i = 1:M
    for j = 1:N
        grayLevel = double(Ieq(i,j)) + 1;
        histEnhanced(grayLevel) = ...
            histEnhanced(grayLevel) + 1;
    end
end

%% Display original image
figure; %[output:452d2e24]
imshow(I); %[output:452d2e24]
title('Original Image'); %[output:452d2e24]

%% Display original histogram
figure; %[output:94846c10]
bar(0:L-1, histOriginal); %[output:94846c10]
xlim([0 L-1]); %[output:94846c10]
title('Histogram of Original Image'); %[output:94846c10]
xlabel('Gray Level'); %[output:94846c10]
ylabel('Number of Pixels'); %[output:94846c10]

%% Display transformation function
figure; %[output:26ba2b64]
plot(0:L-1, T, 'LineWidth', 2); %[output:26ba2b64]
xlim([0 L-1]); %[output:26ba2b64]
ylim([0 L-1]); %[output:26ba2b64]
grid on; %[output:26ba2b64]
title('Histogram Equalization Transformation Function T(r)'); %[output:26ba2b64]
xlabel('Input Gray Level r'); %[output:26ba2b64]
ylabel('Output Gray Level s = T(r)'); %[output:26ba2b64]

%% Display enhanced image
figure; %[output:16122dbf]
imshow(Ieq); %[output:16122dbf]
title('Enhanced Image After Histogram Equalization'); %[output:16122dbf]

%% Display enhanced histogram
figure; %[output:32be6267]
bar(0:L-1, histEnhanced); %[output:32be6267]
xlim([0 L-1]); %[output:32be6267]
title('Histogram of Enhanced Image'); %[output:32be6267]
xlabel('Gray Level'); %[output:32be6267]
ylabel('Number of Pixels'); %[output:32be6267]

%% Save enhanced image
imwrite(Ieq, 'Q4_equalized.jpg');


